pub fn run(project_dir: PathBuf, cx: &App) -> Task<Result<BuildOutcome>> {
    cx.background_spawn(async move { build(&project_dir) })
}

/// Runs `piton build` in `project_dir`, waiting for it to finish.
pub fn build(project_dir: &Path) -> Result<BuildOutcome> {
    {
        let output = Command::new("piton")
            .arg("build")
            .current_dir(project_dir)
            .output()?;

        // `piton build` prints each written file on stdout, as an absolute
        // path, and everything else on stderr.
        let root = project_dir
            .canonicalize()
            .unwrap_or_else(|_| project_dir.to_path_buf());
        let files = String::from_utf8_lossy(&output.stdout)
            .lines()
            .map(str::trim)
            .filter(|line| !line.is_empty())
            .map(|line| relative_to(Path::new(line), &root))
            .collect();

        let report = String::from_utf8_lossy(&output.stderr).trim().to_string();
        settings.location = base.clone();

        let folder = settings.create().unwrap();
        assert_eq!(folder, base.join("my new project"));
        for path in ["piton.config.pi", "spec/index.pi", "src", "spec/shape"] {
            assert!(folder.join(path).exists(), "{path} was not created");
        }
        let build = Command::new("piton")
            .arg("build")
            .current_dir(&folder)
            .output()
            .unwrap();
        assert!(
            build.status.success(),
            "piton build failed: {}",
            String::from_utf8_lossy(&build.stderr)
}

/// `text` in Piton's canonical formatting, from `piton format` run in
/// `project_dir`; an error if it could not be formatted.
pub(crate) fn format_piton(text: &str, project_dir: &Path) -> anyhow::Result<String> {
    use std::io::Write as _;
    use std::process::{Command, Stdio};

    let mut child = Command::new("piton")
        .args(["format", "-"])
        .current_dir(project_dir)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()?;
